    new_roads = roads.copy()

    # Find cities reachable from each city, including the effect of the new taxes
    reachable_cities = {i: 0 for i in range(n)}
    for city in range(n):
        for next_city in new_roads[city]:
            reachable_cities[next_city] = max(reachable_cities[next_city], new_h[next_city])

    losing_cities = [city for city in reachable_cities if reachable_cities[city] <= 0]

    # Choose a city to decrease taxes in to the lexicographically minimal value among the losing cities
    for city in sorted(losing_cities):
        if new_h[city] > 0:
            new_h[city] = 0

    return new_h

# Function to simulate a move by the Time Limit Exceeded Party
def simulate_timelimit_exceeded_move(old_h, new_h):
    # The Time Limit Exceeded Party can decrease taxes in the cities earlier modified by the Wrong Answer Party
    for city in range(n):
        if old_h[city] > 0:
            new_h[city] = min(new_h[city], old_h[city])

    return new_h

