def max_goods_sold(n, c, production, sellable):
    # Length of the lookup table
    mem = [[0 for _ in sellable] for _ in production]

    @lru_cache(None)
    def dfs(i, j):
        # If there are no more cities to transport, all goods in current city can be sold
        if j == c + 1:
            mem[i][j] = sum(s for s in sellable[i:])
        else:
            # Try allocating goods from all previous units shipped
            for s in range(productions[i] + 1):
                mem[i][j] = max(mem[i] [j], sales[s] + dfs(i + 1, j + 1) - dfs(i + 1, s))
        return mem[i][j]

