    hauptaltar_structure = [('L', 'T', 1, 3), ('L', 'B', 2, 2), ('L', 'B', 3, 3),
                            ('T', 'R', 1, 2), ('T', 'B', 2, 1), ('T', 'R', 4, 1),
                            ('B', 'R', 4, 3)]

