from heapq import heappush, heappop

def minCleaningTime(testcases):
    for _ in range(testcases):
        N, M = map(int, input().split())
        workers = []
        for _ in range(M + 1):
            L, R = map(int, input().split())
            workers.append((R - L, -L, R))
        workers.sort()

        visited = [False] * N
        pq = [(0, 0)]  # (time, current index)
        while pq:
            time, i = heappop(pq)
            if visited[i]:
                continue
            visited[i] = True
            for l, je, re in workers:
                if i + l > re:
                    continue
                if not visited[i - l]:
                    heappush(pq, (time + 1, i - l))
                if not visited[i + 1]:
                    heappush(pq, (time + 1, i + 1))

        if all(visited):
            print(0)
        else:
            print(-1)

