from collections import defaultdict

def merge_interval(start, end):
    if start > end:
        return [end - 1]
    elif start == end:
        return [start]
    else:
        return [start, end]

def get_extremes(points):
    max_x, min_x, max_y, min_y = float('-inf'), float('inf'), float('-inf'), float('inf')
    for x, y in points:
        max_x, min_x = max(max_x, x), min(min_x, x)
        max_y, min_y = max(max_y, y), min(min_y, y)
    return max_x, max_y, min_x, min_y

def next_interval(points):
    max_x, max_y, min_x, min_y = get_extremes(points)
    for x, y in sorted(list(set(points))):
        yield merge_interval(x-x, y-y)

def process_query(points, query):
    for order in next_interval(points):
        points.remove(query)
        points.extend(order)
        yield len(points)

