from collections import Counter
from bisect import bisect

def solve(n, m, sequence):
    count = Counter()
    total = 0
    for num in sequence:
        if count.get(num):
            if num == m:
                if count[num] % 2 == 0:
                    total += count[num] // 2
                else:
                    total += count[num] * (count[num] - 1) // 2
            else:
                total += count[num]
        count[num] += 1
        if num > m:
            count[num + 1] += 1
            count[num - (m - num + 1)] -= 1
        elif num < m:
            count[m - (num - m + 1)] += 1
            count[m] -= 1
        while count[m - 1] == 0:
            count.pop(m - 1)
            m -= 1
    return total

