                anti_bottle_neck = (i, -1)
                break

    # Calculate loss in taxes needed to catch up in anti_bottle_neck
    for j in range(m):
        if roads[j][0] == anti_bottle_neck[0] and roads[j][1] == anti_bottle_neck[1]:
            loss = taxes[anti_bottle_neck[0]] - taxes[roads[j][1]] + 1
            taxes[anti_bottle_neck[0]] += loss
            taxes[roads[j][1]] += -loss
            break

# Determine who wins based on the win condition
if len(possible_routes) % 2 == 1:
    print("WIN")
    print(" ".join(map(str, taxes[:n])))
else:
