@dataclass
class DayResult:
    quantity: int
    minimum_displeasure: int

def calculate_minimum_displeasure(n_songs, songs, days_to_calculate, parameters):
    np_songs = np.array(songs)
    np_songs[~np.isfinite(np_songs)] = 0  # Normalize to integers
    np_songs = np.min(np_songs, axis=0).astype(int)

    results = []
    for day_param in parameters:

        x = day_param.song_quality
        li = day_param.lower
        ri = day_param.upper

        first_day_result = None
        last_day_result = None

        for i in range(li, ri):
            quantity = np_songs[i:i + n_songs - 1].argmin()
            if first_day_result is None:
                first_day_result = DayResult(i, quantity)
            else:
                first_day_result.quantity = quantity

        for i in range(1, li - 1):
            if first_day_result.quantity >= (x + i) // 63 * 63:
                day_results = []
                sum_quality = 0
                while first_day_result.quantity >= x // 63 * 63:
                    day_results.append(first_day_result)
                    sum_quality += i * first_day_result.quantity
                    first_day_result = DayResult(0, x // 63 * 63)
                    i = ri
                for j, result in enumerate(day_results):
                    day_results[j] = DayResult(result.quantity + i, result.minimum_displeasure + sum_quality)

        day_results = []
        for result in day_results:
            if result.quantity == 0:
                results.append(None)
                continue
            quantity = result.quantity + (x + li) // 63 * 63
            while quantity > x:
                quantity -= 63
            day_results.append(DayResult(result.quantity + quantity, result.minimum_displeasure + day_param.song_quality))
            results.append(result.quantity)
        results = sorted(list(filter(None.__ne__, results)))

        for i in range(0, len(results), 490):
            results[i:i+490] = [results[i], results[i+1], results[i+2], results[i+3], first_day_result.quantity + x//63*63, first_day_result.quantity + (x + li) // 63 * 63]

        last_day_result = DayResult(results[0], 0)

        change = False

        for i in range(1, len(results)):
            if results[i-1] > results[i]:
                change = True
                last_day_result = results[i-1]
            elif not change and results[i] > last_day_result:
                change = True
                last_day_result = results[i]
            else:
                continue

            while last_day_result.quantity >= (x + li - j - i // 30 - 1) // 63 * 63:
                last_day_result = DayResult(last_day_result.quantity + 63, last_day_result.minimum_displeasure + j)

    return np.array(results[:days_to_calculate])


if __name__ == "__main__":
    n_songs, m_songs = map(int, input().split())
    songs = list(map(int, input().split()))
