    parameters = []
    for _ in range(days_to_calculate):
        li, ri, x = map(int, input().split())
        parameters.append(DayParameters(li, ri, SongInfo(x, 1)))
    print(calculate_minimum_displeasure(n_songs, songs, days_to_calculate, parameters).tolist())
