from collections import deque

def min_steps_to_introduce_guests(n, m, friendships):
    visited = [False] * (n + 1)
    connections = [[] for _ in range(n + 1)]

    # Build adjacency list representing the initial graph of friendships
    for u, v in friendships:
        connections[u].append(v)
        connections[v].append(u)
        visited[u] = True
        visited[v] = True

    def bfs(start):
        queue = deque([start])
        visited[start] = True
        steps = 0
        while queue:
            steps += 1
            for _ in range(len(queue)):
                current = queue.popleft()
                for neighbor in connections[current]:
                    if not visited[neighbor]:
                        queue.append(neighbor)
                        visited[neighbor] = True
        return steps - 1

    current = max(1, n // 2) if n % 2 else 1
    steps = {(current): bfs(current)}

    while len(visited) < n:
        for guest in range(1, n + 1):
            if not visited[guest] and guest not in steps:
                steps[guest] = bfs(guest)
        current = min(guest for guest in steps if steps[guest] == min(steps))
        if current != n:
            visited[current] = True

    return min(steps.values()), [step[0] for step in steps]

# Example usage
n, m = map(int, input().split())
friendships = [list(map(int, input().split())) for _ in range(m)]
