import sys

def count_palindromes(s):
    n = len(s)
    dp = [[0 for _ in range(n)] for _ in range(n)]

    i = 0
    while i < n:
        if i == 0:
            dp[i][i] = 1
        elif i == 1:
            dp[i][i-1] = 1
        elif s[i-2] == s[i-1]:
            dp[i-1][i-1] = 1
        else:
            dp[i-1][i-1] = 0
        if s[i-2] == s[i-1]:
            dp[i-1][i-1] += 1
            dp[i-1][i-1] -= dp[i-2][i-2]
        i += 1

    result = 0
    for l in range(2, n+1):
        i = 0
        while i < n:
            count = 0
            while i + l - 1 < n and all(dp[j-1][i] for j in range(i, min(n, i+l-1))):
                count += 1
                i += 1
            result += count * (count + 1) // 2
    return result

