def is_palindrome(s):
    return s == s[::-1]

def find_prefix_suffix_palindromes(a, b):
    palindromes = set()
    A = sorted(a)
    B = sorted(b)
    for i in range(len(A)):
        for j in range(len(B)):
            for k in range(1, len(A) - len(A[i:])):
                if is_palindrome(A[i:i+k]):
                    for l in range(1, len(B) - len(B[j:])):
                        if is_palindrome(B[j:j+l]):
                            palindromes.add(A[i:i+k] + B[j:j+l])
                        break
            break

    return palindromes

def count_unique_strings(a, b):
    prefix_palindromes = find_prefix_suffix_palindromes(a, b)
    suffix_palindromes = find_prefix_suffix_palindromes(b, a)

    both_palindromes = prefix_palindromes | suffix_palindromes
    return len(both_palindromes)

