from collections import defaultdict

def find_points(add, remove, points):
    return len(points) - (remove if add else len(points))

def extend_set(points, add_query, remove_query):
    x_abs_sum = defaultdict(int)
    y_abs_sum = defaultdict(int)

    # Precompute the sum of absolute values of x/y of all points in points
    for x, y in points:
        x_abs_sum[x] += x * x
        y_abs_sum[y] += y * y

    query_pos = defaultdict(lambda: defaultdict(int))
    for query in add_query + remove_query:
        x, y = query
        if x == 0:
            if x_abs_sum[x]:
                query_pos[y][x_abs_sum[x // x_abs_sum[y]]] += 1
                query_pos[y][x_abs_sum[y] - x_abs_sum[x]] -= 1
        elif y == 0:
            if y_abs_sum[y]:
                query_pos[x][y_abs_sum[y // y_abs_sum[x]]] += 1
                query_pos[x][y_abs_sum[x] - y_abs_sum[y]] -= 1
        else:
            query_pos[x][add_query[0][0]] = query_pos[y][remove_query[0][0]] = add_query[0][0]

    # Compute E(S)
    new_points = set()
    for x, y in points:
        if query_pos[x][add_query[0][0]] == 0 and query_pos[y][remove_query[0][0]] == 0:
            if x == 0 and y == 0:
                x_abs = -x_abs_sum[x]
                y_abs = y_abs_sum[y]
            else:
                x_abs = x_abs_sum[x] - add_query[0][0]
                y_abs = y_abs_sum[y] - remove_query[0][0]
            if (x_abs, y_abs) not in new_points:  
                new_points.add((x_abs, y_abs))

    return len(new_points)

