        while i < n or j < m:
            while i < n and p[i][1] == j:
                result.append('L' if p[i][0] == 'L' else 'R')
                i += 1
            while j < m and p[j][1] == i:
                result.append('U' if p[j][0] == 'U' else 'D')
                j += 1
            if i >= n and j >= m:
                break
            i += 2 if p[i - 1][1] == 'T' else -1
            j += 2 if p[j - 1][1] == 'T' else -1
        return ''.join(result[::-1])

    def distribute_pins(p):
        for i, j, k in pins:
            rows = [p.index((i, j)), p.index((i, k))]
            cols = [p.index((j, k)), p.index((j, i)), p.index((k, i)), p.index((k, j))]
            rows.sort()
            cols.sort()
            for r in rows:
                p[r[0]] = (r[0] + k - rows[0], rows[1])
            for c in cols:
                p[c[0]] = (c[0] + i - cols[0], cols[1])

    grid = [['L', 'T', 'R', 'B'] for _ in range(n + m)]
    distribute_pins(grid)
    max_diff = 0
    for i in range(1, n + 1):
        diff = max_diff - (grid[i].count('T') - grid.count('B'))
        if diff < 0:
            diff = -diff
        if max_diff == 0 or diff - max_diff >= 2:
