            # Calculate the sliding window for the knight
            left = knight[0]
            right = knight[1] + 1

            while left >= 0 and right <= N-1 and not visited[left]:
                visited[left] = True
                left -= 1
                right += 1

            # Update the maximum knight's x-coordinate if needed
            if max_knight is None:
                max_knight = right - 1
            else:
                max_knight = max(max_knight, right - 1)

        # Check if all positions are filled
        if all(visited):
            print(max_knight)
        else:
            print(-1)

