from collections import defaultdict

def min_steps_to_connect(guests, friends):
    n = len(guests)
    adj_list = defaultdict(list)
    for frm, to in friends:
        adj_list[frm].append(to)
        adj_list[to].append(frm)

    def bfs(source):
        visited = [False] * n
        queue = [source]
        step = 0
        while queue:
            new_queue = []
            for i in queue:
                for neighbor in adj_list[i]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        new_queue.append(neighbor)
            queue = new_queue
            if all(visited):
                break
            step += 1
        return step

    min_steps = float('inf')
    optimal_step = None
    for i in range(guests):
        current_step = bfs(i)
        if current_step < min_steps:
            min_steps = current_step
            optimal_step = [i + 2]  # Convert index to corresponding guest ID
    for j in range(i + 1, guests):
        if all(guests[k] in adj_list[guests[j]] for k in range(i)):
            optimal_step.append(j + 2)
            break
    print(min_steps)
    print(optimal_step)
