from bisect import bisect_left

def maximize_selling_goods(n, c, pi, si):
    nages = [0] * n
    ng = {}

    for i, p in enumerate(pi):
        m = max(p, si[i])
        nages[i] = m
        if m in ng:
            left_over = ng[m] - (m + 1 - c)
            nages[ng[m]] -= left_over
            ng[m] += (left_over == 0) + (i < ng[m])
        else:
            ng[m] = i

    return sum(abs(x - s) for x, s in zip(nages, si))

